import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"19、【臨】 兌下坤上","description":"周易口訣義 - 19、【臨】 兌下坤上","frontmatter":{"title":"19、【臨】 兌下坤上","description":"周易口訣義 - 19、【臨】 兌下坤上"},"headers":[],"relativePath":"classics/koujueyi/021.md","filePath":"classics/koujueyi/021.md"}'),r={name:"classics/koujueyi/021.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_19、【臨】-兌下坤上" tabindex="-1">19、【臨】 兌下坤上 <a class="header-anchor" href="#_19、【臨】-兌下坤上" aria-label="Permalink to “19、【臨】 兌下坤上”">​</a></h1><p>彖曰：「臨」，剛浸而長，說而順，剛中而應。大亨以正，天之道也。至於八月有兇，消不久也。</p><p>象曰：澤上有地，「臨」。君子以教思無窮，容保民無疆。</p><p>初九：鹹臨，貞吉。</p><p>象曰：「鹹臨貞吉」，志行正也。</p><p>九二：鹹臨，吉，無不利。</p><p>象曰：「鹹臨吉無不利」，未順命也。</p><p>六三：甘臨，無攸利。既憂之，無咎。</p><p>象曰：「甘臨」，位不當也。「既憂之」，咎不長也。</p><p>六四：至臨，無咎。</p><p>象曰：「至臨無咎」，位當也。</p><p>六五：知臨，大君之宜，吉。</p><p>象曰：「大君之宜」，行中之謂也。</p><p>上六：敦臨，吉，無咎。</p><p>象曰：「敦臨」之吉，志在內也。</p><p>解讀</p><p>「臨元亨利貞」者，臨，大也，以陽氣方長，萬物皆盛，亦猶王者盛大之德，威臨於下，故稱「臨」也。凡物盛之時，能備四德，故曰「元亨利貞」也。「至於八月有兇」者，夫盛極必衰，自然常理，臨為盛大之卦，故以垂戒之。言「兇」者，臨卦是建醜之月卦，陽氣方長，至及八月，即四陰已長，四陽卻退，小人道長，君子道消也，故曰「八月有兇」也。</p><p>象曰：「澤上有地，臨」者，是以大臨小，以高臨下之義也。「君子以教思無窮，容保民無疆」者，凡為君長以臨，當須教化思念，無有窮已，又須含容保愛民人，人即歸德邊境，不計遠邇也。</p><p>「初九，鹹臨，貞吉」者，鹹，感也；以陽感應於陰，相感而臨，志行其正，故曰「貞吉」也。</p><p>「九二，鹹臨，吉，無不利」者，以陽應陰，相感而臨也。二是剛陽，五是柔陰，若全順於五，則剛德全損，全與相違，又失感應之道，必須量時進退，如君臣獻可替否之義，故得「吉，無不利」。</p><p>六三，甘臨，無攸利。「既憂之，無咎」者，以陰居陽，即是越陰柔之道，小人之行也。甘謂言辭甘美，邪佞不正之名也。六三以邪謟之行以臨於物，患必生焉，故無施而利，故曰「甘臨，無攸利」。若能恆憂其危，改過自新，乃得無咎，故曰「既憂之，無咎」也。</p><p>六四至臨無咎者，以陰應陽，不懼剛長，以至極之善而應臨於初，乃得「無咎」也。</p><p>六五知臨，大君之宜，吉者，以柔處尊，納剛以禮，不以威武是用，而知臨於物，如似「大君之宜」，所以獲「吉」也。</p><p>「上六敦臨，吉無咎」者，敦，厚也，處坤之極，即是敦厚以為臨也。處於上體，志在尊賢，故獲「吉」也。</p>',24)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
